  ["Shake it off"] = "Olvídalo",
  ["Next one!"] = "¡A por la siguiente!",
  ["Great streak!"] = "¡Gran racha!",
  ["Keep it up!"] = "¡Sigue así!",
  ["Blazing!"] = "¡Ardiente!",
  ["Streak Champion!"] = "¡Campeón de rachas!",
  ["Godlike!"] = "¡Divino!",
  ["Immortal!"] = "¡Inmortal!",
  ["Game timing offset"] = "Desfase de tiempo del modo juego",
  ["Game mode: moves the moment a note reaches the line (and flashes). If your presses feel late, raise it: the note arrives that much sooner. Like a rhythm game's calibration."] = "Modo juego: mueve el momento en que una nota llega a la línea (y destella). Si tus pulsaciones van tarde, súbelo: la nota llega ese tiempo antes. Como la calibración de un juego de ritmo.",
  ["Game score %d, best streak %d, %d%% perfect"] = "Puntos de juego %d, mejor racha %d, %d%% perfectos",
  ["(new high score)"] = "(nuevo récord)",
}
